    handle: *c.TA_CDLBREAKAWAY_Stream,
    begidx: i32,

    /// Warm up on the history (leading NaN bars are skipped) and start a stream.
    pub fn init(open: []const f64, high: []const f64, low: []const f64, close: []const f64) !CDLBREAKAWAY {
        const length = try checkLength4(open, high, low, close);
        if (length == 0) return TAError.InsufficientHistory;
        const begidx = checkBegIdx4(length, open, high, low, close);
        var handle: ?*c.TA_CDLBREAKAWAY_Stream = null;
        var outinteger: i32 = undefined;
        try convertRetCode(c.TA_CDLBREAKAWAY_Open(&handle, open[begidx..].ptr, high[begidx..].ptr, low[begidx..].ptr, close[begidx..].ptr, @intCast(length - begidx), &outinteger));
        return .{ .handle = handle.?, .begidx = @intCast(begidx) };
    }

    /// Like `init`, but also returns the batch output over the history.
    pub fn initAndFill(allocator: std.mem.Allocator, open: []const f64, high: []const f64, low: []const f64, close: []const f64) !struct {
        stream: CDLBREAKAWAY,
        integer: []i32,
    } {
        var outbegidx: i32 = undefined;
        var outnbelement: i32 = undefined;
        const length = try checkLength4(open, high, low, close);
        if (length == 0) return TAError.InsufficientHistory;
        const begidx = checkBegIdx4(length, open, high, low, close);
        const lookback = begidx + try checkLookback(c.TA_CDLBREAKAWAY_Lookback());
        const outidx = @min(lookback, length);
        var outinteger = try makeIntArray(allocator, length, lookback);
        errdefer allocator.free(outinteger);
        var handle: ?*c.TA_CDLBREAKAWAY_Stream = null;
        try convertRetCode(c.TA_CDLBREAKAWAY_OpenAndFill(&handle, open[begidx..].ptr, high[begidx..].ptr, low[begidx..].ptr, close[begidx..].ptr, @intCast(length - begidx), &outbegidx, &outnbelement, outinteger[outidx..].ptr));
        return .{
            .stream = .{ .handle = handle.?, .begidx = @intCast(begidx) },
            .integer = outinteger,
        };
    }

    /// Commit one closed bar and return its output.
    pub fn update(self: *CDLBREAKAWAY, open: f64, high: f64, low: f64, close: f64) TAError!i32 {
        var outinteger: i32 = undefined;
        try convertRetCode(c.TA_CDLBREAKAWAY_Update(self.handle, open, high, low, close, &outinteger));
        return outinteger;
    }

    /// Return what `update` would for this bar, without committing it.
    pub fn peek(self: *const CDLBREAKAWAY, open: f64, high: f64, low: f64, close: f64) TAError!i32 {
        var outinteger: i32 = undefined;
        try convertRetCode(c.TA_CDLBREAKAWAY_Peek(self.handle, open, high, low, close, &outinteger));
        return outinteger;
    }

    /// The output at the last bar the stream counted.
    pub fn value(self: *const CDLBREAKAWAY) TAError!i32 {
        var outinteger: i32 = undefined;
        try convertRetCode(c.TA_CDLBREAKAWAY_Value(self.handle, &outinteger));
        return outinteger;
    }

    /// The bars this stream has an output for, in the input series' coordinates.
    pub fn outRange(self: *const CDLBREAKAWAY) TAError!OutRange {
        var outbegidx: i32 = undefined;
        var outnbelement: i32 = undefined;
        try convertRetCode(c.TA_CDLBREAKAWAY_OutRange(self.handle, &outbegidx, &outnbelement));
        return .{ .begidx = @intCast(outbegidx + self.begidx), .nbelement = @intCast(outnbelement) };
    }

    /// Count one bar the stream was not fed; `value` keeps the previous output.
    pub fn advance(self: *CDLBREAKAWAY) TAError!void {
        try convertRetCode(c.TA_CDLBREAKAWAY_Advance(self.handle));
    }

    /// Fork the stream; both must be released with `deinit`.
    pub fn clone(self: *const CDLBREAKAWAY) TAError!CDLBREAKAWAY {
        var handle: ?*c.TA_CDLBREAKAWAY_Stream = null;
        try convertRetCode(c.TA_CDLBREAKAWAY_Clone(self.handle, &handle));
        return .{ .handle = handle.?, .begidx = self.begidx };
    }

    pub fn deinit(self: *CDLBREAKAWAY) void {
        _ = c.TA_CDLBREAKAWAY_Close(self.handle);
        self.* = undefined;
    }
};

