/// Indexes of lowest and highest values over a specified period
pub const MINMAXINDEX = struct {
    handle: *c.TA_MINMAXINDEX_Stream,
    begidx: i32,

    pub const Output = struct {
        minidx: i32,
        maxidx: i32,
    };

    /// Warm up on the history (leading NaN bars are skipped) and start a stream.
    pub fn init(real: []const f64, timeperiod: i32) !MINMAXINDEX {
        const length = real.len;
        if (length == 0) return TAError.InsufficientHistory;
        const begidx = checkBegIdx1(length, real);
        var handle: ?*c.TA_MINMAXINDEX_Stream = null;
        var outminidx: i32 = undefined;
        var outmaxidx: i32 = undefined;
        try convertRetCode(c.TA_MINMAXINDEX_Open(&handle, real[begidx..].ptr, @intCast(length - begidx), timeperiod, &outminidx, &outmaxidx));
        return .{ .handle = handle.?, .begidx = @intCast(begidx) };
    }

    /// Like `init`, but also returns the batch output over the history.
    pub fn initAndFill(allocator: std.mem.Allocator, real: []const f64, timeperiod: i32) !struct {
        stream: MINMAXINDEX,
        minidx: []i32,
        maxidx: []i32,
    } {
        var outbegidx: i32 = undefined;
        var outnbelement: i32 = undefined;
        const length = real.len;
        if (length == 0) return TAError.InsufficientHistory;
        const begidx = checkBegIdx1(length, real);
        const lookback = begidx + try checkLookback(c.TA_MINMAXINDEX_Lookback(timeperiod));
        const outidx = @min(lookback, length);
        var outminidx = try makeIntArray(allocator, length, lookback);
        errdefer allocator.free(outminidx);
        var outmaxidx = try makeIntArray(allocator, length, lookback);
        errdefer allocator.free(outmaxidx);
        var handle: ?*c.TA_MINMAXINDEX_Stream = null;
        try convertRetCode(c.TA_MINMAXINDEX_OpenAndFill(&handle, real[begidx..].ptr, @intCast(length - begidx), timeperiod, &outbegidx, &outnbelement, outminidx[outidx..].ptr, outmaxidx[outidx..].ptr));
        for (outidx..length) |i| {
            outminidx[i] += @intCast(begidx);
        }
        for (outidx..length) |i| {
            outmaxidx[i] += @intCast(begidx);
        }
        return .{
            .stream = .{ .handle = handle.?, .begidx = @intCast(begidx) },
            .minidx = outminidx,
            .maxidx = outmaxidx,
        };
    }

    /// Commit one closed bar and return its output.
    pub fn update(self: *MINMAXINDEX, real: f64) TAError!Output {
        var outminidx: i32 = undefined;
        var outmaxidx: i32 = undefined;
        try convertRetCode(c.TA_MINMAXINDEX_Update(self.handle, real, &outminidx, &outmaxidx));
        return .{
            .minidx = outminidx + self.begidx,
            .maxidx = outmaxidx + self.begidx,
        };
    }

    /// Return what `update` would for this bar, without committing it.
    pub fn peek(self: *const MINMAXINDEX, real: f64) TAError!Output {
        var outminidx: i32 = undefined;
        var outmaxidx: i32 = undefined;
        try convertRetCode(c.TA_MINMAXINDEX_Peek(self.handle, real, &outminidx, &outmaxidx));
        return .{
            .minidx = outminidx + self.begidx,
            .maxidx = outmaxidx + self.begidx,
        };
    }

    /// The output at the last bar the stream counted.
    pub fn value(self: *const MINMAXINDEX) TAError!Output {
        var outminidx: i32 = undefined;
        var outmaxidx: i32 = undefined;
        try convertRetCode(c.TA_MINMAXINDEX_Value(self.handle, &outminidx, &outmaxidx));
        return .{
            .minidx = outminidx + self.begidx,
            .maxidx = outmaxidx + self.begidx,
        };
    }

    /// The bars this stream has an output for, in the input series' coordinates.
    pub fn outRange(self: *const MINMAXINDEX) TAError!OutRange {
        var outbegidx: i32 = undefined;
        var outnbelement: i32 = undefined;
        try convertRetCode(c.TA_MINMAXINDEX_OutRange(self.handle, &outbegidx, &outnbelement));
        return .{ .begidx = @intCast(outbegidx + self.begidx), .nbelement = @intCast(outnbelement) };
    }

    /// Count one bar the stream was not fed; `value` keeps the previous output.
    pub fn advance(self: *MINMAXINDEX) TAError!void {
        try convertRetCode(c.TA_MINMAXINDEX_Advance(self.handle));
    }

    /// Fork the stream; both must be released with `deinit`.
    pub fn clone(self: *const MINMAXINDEX) TAError!MINMAXINDEX {
        var handle: ?*c.TA_MINMAXINDEX_Stream = null;
        try convertRetCode(c.TA_MINMAXINDEX_Clone(self.handle, &handle));
        return .{ .handle = handle.?, .begidx = self.begidx };
    }

    pub fn deinit(self: *MINMAXINDEX) void {
        _ = c.TA_MINMAXINDEX_Close(self.handle);
        self.* = undefined;
    }
};

