/// Zig Zag
pub const ZIGZAG = struct {
    handle: *c.TA_ZIGZAG_Stream,
    begidx: i32,

    pub const Output = struct {
        zigzag: f64,
        trend: i32,
        pivotidx: i32,
    };

    /// Warm up on the history (leading NaN bars are skipped) and start a stream.
    pub fn init(high: []const f64, low: []const f64, sensitivity: f64, mintrendlength: i32) !ZIGZAG {
        const length = try checkLength2(high, low);
        if (length == 0) return TAError.InsufficientHistory;
        const begidx = checkBegIdx2(length, high, low);
        var handle: ?*c.TA_ZIGZAG_Stream = null;
        var outzigzag: f64 = undefined;
        var outtrend: i32 = undefined;
        var outpivotidx: i32 = undefined;
        try convertRetCode(c.TA_ZIGZAG_Open(&handle, high[begidx..].ptr, low[begidx..].ptr, @intCast(length - begidx), sensitivity, mintrendlength, &outzigzag, &outtrend, &outpivotidx));
        return .{ .handle = handle.?, .begidx = @intCast(begidx) };
    }

    /// Like `init`, but also returns the batch output over the history.
    pub fn initAndFill(allocator: std.mem.Allocator, high: []const f64, low: []const f64, sensitivity: f64, mintrendlength: i32) !struct {
        stream: ZIGZAG,
        zigzag: []f64,
        trend: []i32,
        pivotidx: []i32,
    } {
        var outbegidx: i32 = undefined;
        var outnbelement: i32 = undefined;
        const length = try checkLength2(high, low);
        if (length == 0) return TAError.InsufficientHistory;
        const begidx = checkBegIdx2(length, high, low);
        const lookback = begidx + try checkLookback(c.TA_ZIGZAG_Lookback(sensitivity, mintrendlength));
        const outidx = @min(lookback, length);
        var outzigzag = try makeDoubleArray(allocator, length, lookback);
        errdefer allocator.free(outzigzag);
        var outtrend = try makeIntArray(allocator, length, lookback);
        errdefer allocator.free(outtrend);
        var outpivotidx = try makeIntArray(allocator, length, lookback);
        errdefer allocator.free(outpivotidx);
        var handle: ?*c.TA_ZIGZAG_Stream = null;
        try convertRetCode(c.TA_ZIGZAG_OpenAndFill(&handle, high[begidx..].ptr, low[begidx..].ptr, @intCast(length - begidx), sensitivity, mintrendlength, &outbegidx, &outnbelement, outzigzag[outidx..].ptr, outtrend[outidx..].ptr, outpivotidx[outidx..].ptr));
        for (outidx..length) |i| {
            outpivotidx[i] += @intCast(begidx);
        }
        return .{
            .stream = .{ .handle = handle.?, .begidx = @intCast(begidx) },
            .zigzag = outzigzag,
            .trend = outtrend,
            .pivotidx = outpivotidx,
        };
    }

    /// Commit one closed bar and return its output.
    pub fn update(self: *ZIGZAG, high: f64, low: f64) TAError!Output {
        var outzigzag: f64 = undefined;
        var outtrend: i32 = undefined;
        var outpivotidx: i32 = undefined;
        try convertRetCode(c.TA_ZIGZAG_Update(self.handle, high, low, &outzigzag, &outtrend, &outpivotidx));
        return .{
            .zigzag = outzigzag,
            .trend = outtrend,
            .pivotidx = outpivotidx + self.begidx,
        };
    }

    /// Return what `update` would for this bar, without committing it.
    pub fn peek(self: *const ZIGZAG, high: f64, low: f64) TAError!Output {
        var outzigzag: f64 = undefined;
        var outtrend: i32 = undefined;
        var outpivotidx: i32 = undefined;
        try convertRetCode(c.TA_ZIGZAG_Peek(self.handle, high, low, &outzigzag, &outtrend, &outpivotidx));
        return .{
            .zigzag = outzigzag,
            .trend = outtrend,
            .pivotidx = outpivotidx + self.begidx,
        };
    }

    /// The output at the last bar the stream counted.
    pub fn value(self: *const ZIGZAG) TAError!Output {
        var outzigzag: f64 = undefined;
        var outtrend: i32 = undefined;
        var outpivotidx: i32 = undefined;
        try convertRetCode(c.TA_ZIGZAG_Value(self.handle, &outzigzag, &outtrend, &outpivotidx));
        return .{
            .zigzag = outzigzag,
            .trend = outtrend,
            .pivotidx = outpivotidx + self.begidx,
        };
    }

    /// The bars this stream has an output for, in the input series' coordinates.
    pub fn outRange(self: *const ZIGZAG) TAError!OutRange {
        var outbegidx: i32 = undefined;
        var outnbelement: i32 = undefined;
        try convertRetCode(c.TA_ZIGZAG_OutRange(self.handle, &outbegidx, &outnbelement));
        return .{ .begidx = @intCast(outbegidx + self.begidx), .nbelement = @intCast(outnbelement) };
    }

    /// Count one bar the stream was not fed; `value` keeps the previous output.
    pub fn advance(self: *ZIGZAG) TAError!void {
        try convertRetCode(c.TA_ZIGZAG_Advance(self.handle));
    }

    /// Fork the stream; both must be released with `deinit`.
    pub fn clone(self: *const ZIGZAG) TAError!ZIGZAG {
        var handle: ?*c.TA_ZIGZAG_Stream = null;
        try convertRetCode(c.TA_ZIGZAG_Clone(self.handle, &handle));
        return .{ .handle = handle.?, .begidx = self.begidx };
    }

    pub fn deinit(self: *ZIGZAG) void {
        _ = c.TA_ZIGZAG_Close(self.handle);
        self.* = undefined;
    }
};

/// Zero-Lag Exponential Moving Average
pub const ZLEMA = struct {
    handle: *c.TA_ZLEMA_Stream,
    begidx: i32,

    /// Warm up on the history (leading NaN bars are skipped) and start a stream.
    pub fn init(real: []const f64, timeperiod: i32) !ZLEMA {
        const length = real.len;
        if (length == 0) return TAError.InsufficientHistory;
        const begidx = checkBegIdx1(length, real);
        var handle: ?*c.TA_ZLEMA_Stream = null;
        var outreal: f64 = undefined;
        try convertRetCode(c.TA_ZLEMA_Open(&handle, real[begidx..].ptr, @intCast(length - begidx), timeperiod, &outreal));
        return .{ .handle = handle.?, .begidx = @intCast(begidx) };
    }

    /// Like `init`, but also returns the batch output over the history.
    pub fn initAndFill(allocator: std.mem.Allocator, real: []const f64, timeperiod: i32) !struct {
        stream: ZLEMA,
        real: []f64,
    } {
        var outbegidx: i32 = undefined;
        var outnbelement: i32 = undefined;
        const length = real.len;
        if (length == 0) return TAError.InsufficientHistory;
        const begidx = checkBegIdx1(length, real);
        const lookback = begidx + try checkLookback(c.TA_ZLEMA_Lookback(timeperiod));
        const outidx = @min(lookback, length);
        var outreal = try makeDoubleArray(allocator, length, lookback);
        errdefer allocator.free(outreal);
        var handle: ?*c.TA_ZLEMA_Stream = null;
        try convertRetCode(c.TA_ZLEMA_OpenAndFill(&handle, real[begidx..].ptr, @intCast(length - begidx), timeperiod, &outbegidx, &outnbelement, outreal[outidx..].ptr));
        return .{
            .stream = .{ .handle = handle.?, .begidx = @intCast(begidx) },
            .real = outreal,
        };
    }

    /// Commit one closed bar and return its output.
    pub fn update(self: *ZLEMA, real: f64) TAError!f64 {
        var outreal: f64 = undefined;
        try convertRetCode(c.TA_ZLEMA_Update(self.handle, real, &outreal));
        return outreal;
    }

    /// Return what `update` would for this bar, without committing it.
    pub fn peek(self: *const ZLEMA, real: f64) TAError!f64 {
        var outreal: f64 = undefined;
        try convertRetCode(c.TA_ZLEMA_Peek(self.handle, real, &outreal));
        return outreal;
    }

    /// The output at the last bar the stream counted.
    pub fn value(self: *const ZLEMA) TAError!f64 {
        var outreal: f64 = undefined;
        try convertRetCode(c.TA_ZLEMA_Value(self.handle, &outreal));
        return outreal;
    }

    /// The bars this stream has an output for, in the input series' coordinates.
    pub fn outRange(self: *const ZLEMA) TAError!OutRange {
        var outbegidx: i32 = undefined;
        var outnbelement: i32 = undefined;
        try convertRetCode(c.TA_ZLEMA_OutRange(self.handle, &outbegidx, &outnbelement));
        return .{ .begidx = @intCast(outbegidx + self.begidx), .nbelement = @intCast(outnbelement) };
    }

    /// Count one bar the stream was not fed; `value` keeps the previous output.
    pub fn advance(self: *ZLEMA) TAError!void {
        try convertRetCode(c.TA_ZLEMA_Advance(self.handle));
    }

    /// Fork the stream; both must be released with `deinit`.
    pub fn clone(self: *const ZLEMA) TAError!ZLEMA {
        var handle: ?*c.TA_ZLEMA_Stream = null;
        try convertRetCode(c.TA_ZLEMA_Clone(self.handle, &handle));
        return .{ .handle = handle.?, .begidx = self.begidx };
    }

    pub fn deinit(self: *ZLEMA) void {
        _ = c.TA_ZLEMA_Close(self.handle);
        self.* = undefined;
    }
};
